from html.parser import HTMLParser
import sys

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('br','hr','img','input','meta','link','canvas','col','area','base','embed','source','track','wbr'):
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()
        elif tag in self.tags:
            while self.tags and self.tags[-1] != tag:
                self.errors.append(f'Unclosed: {self.tags.pop()}')
            if self.tags:
                self.tags.pop()

with open('/app/output/final_report.html') as f:
    content = f.read()

